<script setup>
import {t as tr,uiMessage,dateTime,number,fixed,locale} from "./i18n.js";
import {glowStyle} from './statusGlow.js';
import {ref,computed,onMounted,onUnmounted,watch} from 'vue';
import VacuumPanel from './VacuumPanel.vue';
import UtilizationPanel from './UtilizationPanel.vue';
import {utilizationText} from './utilization.js';
import {createScene} from './cleanroom/scene.js';
import {ids,status,nearestWaypoint,nearbyLoadPort} from './cleanroom/navigation.js';
const props=defineProps({fleet:{type:Array,default:()=>[]},active:Boolean,state:Object,now:Number,api:Function});
const utilization=ref(null),overviewTab=ref('scene');
const overviewTabs=computed(()=>[['scene',tr('ui160')],['utilization',tr('ui161')],['timeline',tr('ui162')],['distribution',tr('ui163')],['production',tr('ui164')],['phm',tr('phmTitle')]]);
const sceneActive=computed(()=>props.active&&overviewTab.value==='scene');
watch(locale,()=>engine?.setLocale());
function tabKey(e,index){const move={ArrowRight:1,ArrowLeft:-1,Home:-index,End:overviewTabs.value.length-1-index}[e.key];if(move===undefined)return;e.preventDefault();const next=(index+move+overviewTabs.value.length)%overviewTabs.value.length;overviewTab.value=overviewTabs.value[next][0];e.currentTarget.parentElement.querySelectorAll('[role=tab]')[next].focus();}
const emit=defineEmits(['select']);
const host=ref(),ready=ref(false),failure=ref(''),progress=ref(0),selected=ref(ids[0]),metrics=ref({fps:0,calls:0});
const joystick=ref({x:0,z:0}),listOpen=ref(false);let engine,abort,sequence=0;const keys=new Set();let stickPointer=null;
const machines=computed(()=>ids.map(id=>props.fleet.find(m=>m.equipmentId===id)||{equipmentId:id}));
const machine=computed(()=>machines.value.find(m=>m.equipmentId===selected.value));
const machineStatus=computed(()=>status(machine.value,props.now));
const nearby = computed(()=>ready.value&&sceneActive.value?nearbyLoadPort(props.state):null);
function enterNearby(){if(!nearby.value)return;const id=nearby.value;clear();emit("select",id);}
function clear(){keys.clear();joystick.value={x:0,z:0};engine?.setInput({x:0,z:0});stickPointer=null;}
function syncInput(){engine?.setInput({x:Number(keys.has('d')||keys.has('arrowright'))-Number(keys.has('a')||keys.has('arrowleft'))+joystick.value.x,z:Number(keys.has('s')||keys.has('arrowdown'))-Number(keys.has('w')||keys.has('arrowup'))+joystick.value.z});}
function key(e){if(!sceneActive.value||e.defaultPrevented||e.target.closest?.('button,[role=tab],[role=button]'))return;const k=e.key.toLowerCase();if(k==='enter'){if(e.type==='keydown'&&!e.isComposing&&!/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)&&!e.target.isContentEditable&&nearby.value){e.preventDefault();if(!e.repeat)enterNearby();}return;}if(!['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright'].includes(k))return;if(e.type==='keyup'){keys.delete(k);syncInput();return;}if(!props.active||props.state.mode!=='manual'||props.state.view!=='follow'||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable)return;e.preventDefault();keys.add(k);syncInput();}
function mode(value){clear();props.state.mode=value;if(value==='manual')props.state.view='follow';else{props.state.waypoint=nearestWaypoint(props.state);props.state.pause=0;}}
function view(value){clear();props.state.view=value;}
function stick(e){if(e.type==='pointerdown'){stickPointer=e.pointerId;e.currentTarget.setPointerCapture(e.pointerId);}if(stickPointer!==e.pointerId)return;const r=e.currentTarget.getBoundingClientRect();let x=(e.clientX-r.left-r.width/2)/35,z=(e.clientY-r.top-r.height/2)/35;const n=Math.max(1,Math.hypot(x,z));joystick.value={x:x/n,z:z/n};syncInput();}
function visibility(){clear();engine?.setActive(sceneActive.value&&!document.hidden&&document.hasFocus());}
async function boot(){const ticket=++sequence;abort?.abort();engine?.dispose();engine=null;abort=new AbortController();failure.value='';ready.value=false;progress.value=0;try{const instance=await createScene(host.value,props.state,{signal:abort.signal,onProgress:p=>progress.value=p,onSelect:id=>selected.value=id,onError:message=>{failure.value=message;ready.value=false;clear();},onMetrics:m=>metrics.value=m});if(ticket!==sequence){instance.dispose();return;}engine=instance;engine.setFleet(props.fleet);ready.value=true;engine.setActive(sceneActive.value&&!document.hidden);}catch(e){if(ticket===sequence)failure.value=uiMessage('ui165');}}
watch(()=>props.fleet,v=>engine?.setFleet(v));watch(sceneActive,()=>{clear();engine?.setActive(sceneActive.value&&!document.hidden);});
onMounted(()=>{boot();window.addEventListener('keydown',key);window.addEventListener('keyup',key);window.addEventListener('blur',visibility);window.addEventListener('focus',visibility);document.addEventListener('visibilitychange',visibility);document.addEventListener('focusin',clear);});
onUnmounted(()=>{sequence++;abort?.abort();engine?.dispose();window.removeEventListener('keydown',key);window.removeEventListener('keyup',key);window.removeEventListener('blur',visibility);window.removeEventListener('focus',visibility);document.removeEventListener('visibilitychange',visibility);document.removeEventListener('focusin',clear);});
defineExpose({diagnostics:()=>engine?.metrics()});
</script>
<template>
<nav class="overview-tabs" role="tablist" :aria-label="tr('ui166')"><button v-for="([id,label],index) in overviewTabs" :id="'overview-tab-'+id" :key="id" role="tab" :aria-selected="overviewTab===id" :aria-controls="id==='scene'?'overview-panel-scene':id==='phm'?'overview-panel-phm':'overview-panel-statistics'" :tabindex="overviewTab===id?0:-1" @click="overviewTab=id" @keydown="tabKey($event,index)">{{label}}</button></nav>
<VacuumPanel v-if="overviewTab==='phm'" id="overview-panel-phm" role="tabpanel" aria-labelledby="overview-tab-phm" :fleet="fleet" :api="api" @select="emit('select',$event)" />
<UtilizationPanel id="overview-panel-statistics" role="tabpanel" :aria-labelledby="'overview-tab-'+overviewTab" v-show="!['scene','phm'].includes(overviewTab)" :view="overviewTab" :fleet="fleet" :api="api" @report="utilization=$event" @select="emit('select',$event)" />
<section v-show="overviewTab==='scene'" id="overview-panel-scene" role="tabpanel" aria-labelledby="overview-tab-scene" class="cleanroom" :aria-label="tr('ui167')">
 <div class="cr-heading"><div><span class="cr-kicker">{{tr('cleanroomTwin')}}</span><h2>{{tr('ui168')}} <span>／ AISLE 08</span></h2></div><span class="cr-live">{{tr('ui169')}}</span></div>
 <div class="cr-controls">
  <div class="cr-segment"><button :aria-pressed="state.mode==='auto'" @click="mode('auto')">{{tr('ui170')}}</button><button :aria-pressed="state.mode==='manual'" @click="mode('manual')">{{tr('ui171')}}</button></div>
  <div class="cr-segment"><button :aria-pressed="state.view==='overview'" @click="view('overview')">{{tr('ui172')}}</button><button :aria-pressed="state.view==='follow'" @click="view('follow')">{{tr('ui173')}}</button></div>
  <button @click="listOpen=!listOpen">{{listOpen?tr('hideList'):tr('showList')}}</button>
 </div>
 <div class="cr-stage">
  <div ref="host" class="cr-canvas" :aria-label="tr('ui177')"></div>
  <div v-if="!ready" class="cr-loading" role="status"><p>{{failure||tr('loadingModel',{progress})}}</p><button v-if="failure" @click="boot">{{tr('ui178')}}</button></div>
  <div v-if="ready" class="cr-legend"><span>{{tr('ui179')}}</span><span>{{tr('ui180')}}</span><span>{{tr('ui181')}}</span><span>{{tr('ui182')}}</span></div>
  <article v-if="ready" class="cr-detail" :aria-label="tr('ui183')"><div class="cr-kicker">{{tr('selectedEquipment')}}</div><h3>{{selected}}</h3><p><i class="status-glow status-dot" :data-status="machineStatus.key" :style="glowStyle(machineStatus)"></i>{{machineStatus.label}} <span>{{machine.processing??'—'}} / 4 PM</span></p><small>{{tr('ui021')}} {{machine.success??'—'}} {{tr('ui184')}} {{machine.scrap??'—'}} {{tr('ui185')}} {{machine.faults??'—'}}</small><p v-if="utilization" class="cr-util">{{tr('ui186')}} {{utilizationText(utilization.equipment.find(m=>m.equipmentId===selected),'utilization')}}<br>{{tr('ui187')}} {{utilizationText(utilization.equipment.find(m=>m.equipmentId===selected),'pmUtilization')}}<br><small>{{{today:tr('ui530'),'24h':tr('ui531'),'7d':tr('ui532'),'30d':tr('ui533')}[utilization.period]}} {{tr('ui188')}} {{fixed(utilization.equipment.find(m=>m.equipmentId===selected)?.coverage,1)}}%</small></p><button @click="emit('select',selected)">{{tr('ui189')}}</button></article>
  <div v-if="ready&&state.mode==='manual'&&state.view==='follow'" class="cr-stick" role="group" :aria-label="tr('ui190')" @pointerdown.prevent="stick" @pointermove.prevent="stick" @pointerup="clear" @pointercancel="clear" @lostpointercapture="clear"><span :style="{transform:`translate(${joystick.x*30}px,${joystick.z*30}px)`}">✥</span></div>
  <button v-if="nearby" class="cr-enter" @click="enterNearby"><b>{{nearby}}</b><span>{{tr('ui191')}}</span></button>
  <div class="cr-caption">{{state.mode==='auto'?tr('ui192'):state.view==='overview'?tr('ui193'):tr('ui194')}}<span>{{metrics.fps}} {{tr('ui195')}}</span></div>
 </div>
 <div v-if="listOpen||failure" class="cr-list"><button v-for="m in machines" :key="m.equipmentId" @click="emit('select',m.equipmentId)"><b>{{m.equipmentId}}</b><span :style="{color:status(m,now).color}"><i class="status-glow status-dot" :data-status="status(m,now).key" :style="glowStyle(status(m,now))"></i> {{status(m,now).label}}</span><small>{{tr('ui196')}}</small></button></div>
</section>
</template>
<style scoped>
.overview-tabs{display:flex;gap:6px;overflow-x:auto;padding:6px;margin:8px 0 18px;background:var(--border);border-radius:12px;max-width:100%}.overview-tabs button{flex:1;white-space:nowrap;border:0;border-radius:8px;background:transparent;padding:12px 18px;color:var(--fg);cursor:pointer;font:inherit;font-size:13px}.overview-tabs button[aria-selected=true]{background:var(--accent-strong);color:white;box-shadow:0 2px 8px var(--accent-soft)}.overview-tabs button:focus-visible{outline:2px solid var(--accent-strong);outline-offset:2px}@media(max-width:600px){.overview-tabs button{padding:11px 13px;font-size:12px}}

.cleanroom{border:1px solid var(--border);border-radius:18px;overflow:hidden;background:var(--surface);margin-top:20px;color:var(--fg)}.cr-heading{display:flex;justify-content:space-between;align-items:center;padding:24px 26px 12px}.cr-kicker{font-size:10px;letter-spacing:2px;color:var(--muted)}.cr-heading h2{font-size:24px;margin:8px 0}.cr-heading h2 span{font-size:14px;color:var(--muted);font-weight:400}.cr-live{font-size:12px;color:#2b917c}.cr-controls{display:flex;gap:12px;flex-wrap:wrap;padding:12px 26px 20px}.cr-controls button{background:var(--surface);border:1px solid var(--border);padding:9px 14px;border-radius:7px;color:var(--fg);font-size:13px;cursor:pointer}.cr-segment{display:flex;gap:3px;background:var(--surface-alt);border-radius:8px;padding:3px}.cr-segment button{border:0;background:transparent}.cr-segment button[aria-pressed=true]{background:var(--accent-strong);color: #fff}.cr-stage{position:relative;height: min(72vh,800px);min-height:540px;background:var(--border)}.cr-canvas{position:absolute;inset:0}.cr-canvas :deep(canvas){display:block;touch-action:none}.cr-loading{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;background:#eef4f0e8;padding:20px;text-align:center}.cr-loading button{padding:12px;background:var(--accent-strong);color:white;border:0;border-radius:8px}.cr-detail{position:absolute;right:20px;top:20px;width:260px;padding:20px;background:var(--glass);border:1px solid var(--border);border-radius:12px;box-shadow:0 10px 30px #284e4510}.cr-detail h3{font-size:16px;letter-spacing:.4px;margin:10px 0 16px}.cr-detail p{font-size:13px;display:flex;align-items:center;gap:7px}.cr-detail p span{margin-left:auto}.cr-detail i{width:7px;height:7px;border-radius:50%}.cr-detail small{color:var(--muted);font-size:11px}.cr-detail button{width:100%;margin-top:16px;padding:11px;background:var(--accent-strong);border:0;border-radius:7px;color:white;cursor:pointer}.cr-legend{position:absolute;left:20px;top:20px;display:flex;gap:13px;font-size:11px;padding:9px 12px;border-radius:7px;background:#ffffffd9}.cr-legend span:nth-child(1){color:#21977f}.cr-legend span:nth-child(2){color:#ad9150}.cr-legend span:nth-child(3){color:#df855a}.cr-legend span:nth-child(4){color:#91a2a5}.cr-caption{position:absolute;bottom:0;left:0;right:0;padding:12px 20px;background:#ffffffdf;font-size:11px;color:var(--muted);display:flex;justify-content:space-between;pointer-events:none}.cr-stick{position:absolute;left:25px;bottom:65px;width:110px;height:110px;border-radius:50%;background:#ffffff99;border:2px solid var(--muted);display:grid;place-items:center;touch-action:none;user-select:none}.cr-stick span{display:grid;place-items:center;width:50px;height:50px;border-radius:50%;background:var(--fg);color:white;font-size:24px;pointer-events:none}.cr-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(215px,1fr));gap:10px;padding:20px}.cr-list button{display:flex;flex-direction:column;align-items:flex-start;gap:8px;background:var(--surface-alt);border:1px solid var(--border);padding:16px;border-radius:9px;cursor:pointer}.cr-list small{color:var(--muted)}.cr-enter{position:absolute;left:50%;bottom:55px;transform:translateX(-50%);display:flex;flex-direction:column;gap:6px;background:var(--fg);color:white;border:1px solid #9bd7bc;border-radius:10px;padding:12px 18px;cursor:pointer;box-shadow:0 5px 20px #123c3420;white-space:nowrap}.cr-enter span{font-size:12px}@media(max-width:700px){.cr-enter{bottom:325px;font-size:12px}.cr-enter span{font-size:11px}}@media(max-width:700px){.cr-heading{padding:18px 15px 6px}.cr-heading h2{font-size:19px}.cr-heading h2 span{font-size:11px}.cr-live{font-size:10px}.cr-controls{padding:10px 12px;gap:7px}.cr-controls button{padding:8px;font-size:11px}.cr-stage{height:720px;min-height:0}.cr-canvas{bottom:190px}.cr-detail{left:12px;right:12px;top:auto;bottom:36px;width:auto;padding:13px}.cr-detail h3{font-size:13px}.cr-legend{left:10px;top:10px;gap:9px;font-size:10px}.cr-caption{font-size:9px;padding:10px}.cr-stick{left:12px;bottom:215px;width:95px;height:95px}.cr-detail small{font-size:10px}}
</style>
